"""Validate the sole cache entry regenerated by retained Kubernetes probes.

No business cache, existing metadata entry or private signing material may differ.
The public keys must be backed by certificates in the pinned signing archive.
"""
import base64,json
import javaobj
import jwt
from cryptography import x509
from cryptography.hazmat.primitives.serialization import pkcs12, Encoding


def probe_cache_equivalent(expected, actual, archive, password):
    if set(expected) != set(actual):
        return False
    differences = {name for name in expected if expected[name] != actual[name]}
    if not differences:
        return True
    if differences != {'jwks'} or expected['jwks'] or set(actual['jwks']) != {'oauth-jwks'}:
        return False
    _, certificate, additional = pkcs12.load_key_and_certificates(archive, password)
    trusted = {item.public_bytes(Encoding.DER) for item in ([certificate] if certificate else []) + list(additional or [])}
    value = javaobj.loads(actual['jwks']['oauth-jwks'])
    if set(value) != {'keys'} or not value['keys'] or len(value['keys']) > 64:
        return False
    for key in value['keys']:
        if key.get('kty') not in ('RSA','EC','OKP') or any(name in key for name in ('d', 'p', 'q', 'dp', 'dq', 'qi', 'k')):
            return False
        chain = key.get('x5c')
        if getattr(getattr(chain,'classdesc',None),'name',None)=='java.util.CollSer':
            if chain.tag!=1 or len(chain.annotations)!=2 or chain.annotations[0]!='\x00\x00\x00\x01':
                return False
            chain=[chain.annotations[1]]
        if not chain or base64.b64decode(str(chain[0]), validate=True) not in trusted:
            return False
        cert = x509.load_der_x509_certificate(base64.b64decode(str(chain[0]), validate=True))
        algorithm={'RSA':jwt.algorithms.RSAAlgorithm,'EC':jwt.algorithms.ECAlgorithm,'OKP':jwt.algorithms.OKPAlgorithm}[str(key['kty'])]
        public=json.loads(algorithm.to_jwk(cert.public_key()))
        if any(str(key.get(name)) != str(value) for name,value in public.items() if name!='key_ops'):
            return False
    return True
